#include <napi/native_api.h>
#include <string>
#include "tailnet_go.h"
struct Work { napi_async_work work; napi_deferred deferred; std::string op,a,b,c,result; int fd=-1; };
static void Execute(napi_env,void* data){auto*w=static_cast<Work*>(data);char*r=nullptr;if(w->op=="start")r=tn_start(w->a.data(),w->b.data(),w->c.data());else if(w->op=="database")r=tn_database(w->a.data());else if(w->op=="catalog")r=tn_catalog(w->a.data());else if(w->op=="network")r=tn_network(w->a.data());else if(w->op=="multi")r=tn_multi(w->a.data());else if(w->op=="attach")r=tn_attach(w->fd);else if(w->op=="status")r=tn_status();else if(w->op=="resources")r=tn_resources();else tn_stop();if(r){w->result=r;tn_free(r);}}
static void Complete(napi_env env,napi_status status,void* data){auto*w=static_cast<Work*>(data);napi_value result;napi_create_string_utf8(env,w->result.c_str(),NAPI_AUTO_LENGTH,&result);if(status!=napi_ok||(w->op!="status"&&w->op!="resources"&&w->op!="catalog"&&!w->result.empty())){napi_value error;napi_create_error(env,nullptr,result,&error);napi_reject_deferred(env,w->deferred,error);}else napi_resolve_deferred(env,w->deferred,result);napi_delete_async_work(env,w->work);delete w;}
static bool String(napi_env e,napi_value v,std::string& s){size_t n;if(napi_get_value_string_utf8(e,v,nullptr,0,&n)!=napi_ok||n>4096)return false;s.resize(n+1);if(napi_get_value_string_utf8(e,v,s.data(),s.size(),&n)!=napi_ok)return false;s.resize(n);return true;}
static napi_value Call(napi_env env,napi_callback_info info){napi_value a[4];size_t n=4;napi_get_cb_info(env,info,&n,a,nullptr,nullptr);auto*w=new Work();bool ok=n>=1&&String(env,a[0],w->op);if(ok&&w->op=="start")ok=n==4&&String(env,a[1],w->a)&&String(env,a[2],w->b)&&String(env,a[3],w->c);else if(ok&&(w->op=="multi"||w->op=="network"||w->op=="database"||w->op=="catalog"))ok=n==2&&String(env,a[1],w->a);else if(ok&&w->op=="attach")ok=n==2&&napi_get_value_int32(env,a[1],&w->fd)==napi_ok&&w->fd>=0;else if(ok)ok=n==1&&(w->op=="status"||w->op=="resources"||w->op=="stop");if(!ok){delete w;napi_throw_type_error(env,nullptr,"Invalid tailnet operation");return nullptr;}napi_value promise,name;napi_create_promise(env,&w->deferred,&promise);napi_create_string_utf8(env,"tailnet",NAPI_AUTO_LENGTH,&name);napi_create_async_work(env,nullptr,name,Execute,Complete,w,&w->work);napi_queue_async_work(env,w->work);return promise;}
static napi_value Init(napi_env env,napi_value exports){napi_property_descriptor p={"call",nullptr,Call,nullptr,nullptr,nullptr,napi_default,nullptr};napi_define_properties(env,exports,1,&p);return exports;}
static napi_module module={1,0,nullptr,Init,"tailnet",nullptr,{0}};
extern "C" __attribute__((constructor)) void RegisterTailnet(){napi_module_register(&module);}
